SELECT target_id FROM reactions
WHERE user_id = #{userId} AND target_type = 'drama' AND kind = 'like' AND target_id IN
#{dramaId}

SELECT episode_id AS episode_id, COUNT(*) AS total
FROM comments
WHERE episode_id IN
#{episodeId}
AND status = 'pending' AND user_id = #{userId}
GROUP BY episode_id
